function [s] = modes_step(st, mp, zw, sun_ok, sun, dt)
%MODES_STEP  The transitions of one tick (after safe mode): the detumble exit, the spin guards, the
%   gyro-propagated Sun vector of the acquisition laws, the end of the rotor Sun acquisition.
%   vectors: 96
%   st: Modes (passed rec)
%   mp: ModeParams (passed rec)
%   zw: real[1][3] (passed a plain number)
%   sun_ok: bool (passed true or false)
%   sun: real[1][3] (passed a plain number)
%   dt: real[1] (passed a plain number)
%   returns s: Modes (passed rec)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    s = asils.alg.modes.Modes_zero();
    s = st;
    if ((((s.mode == 0) || (s.mode == 7)) && (mp.auto_next ~= 255)) && (bitand(s.faults, bitor(256, 512)) == 0))
        if (sqrt(zw(1)*zw(1) + zw(2)*zw(2) + zw(3)*zw(3)) < mp.detumble_exit)
            s.hold = (s.hold + dt);
        else
            s.hold = 0;
        end
        if (s.hold >= mp.detumble_hold_s)
            s = asils.alg.modes.modes_enter(s, mp.auto_next);
        end
    end
    if (((s.mode == 5) || (s.mode == 6)) && (mp.ss_law ~= 2))
        s = asils.alg.modes.spin_guards(s, mp, sun_ok, sun, dt);
    end
    if (((s.mode == 5) || (s.mode == 6)) || (s.mode == 8))
        if sun_ok
            s.s_prop = sun;
            s.s_prop_ok = true;
        elseif s.s_prop_ok
            a = asils.alg.math.dcm(asils.alg.math.fromrotvec((s.w_est * dt)));
            h__99 = [a(1, 1)*s.s_prop(1) + a(1, 2)*s.s_prop(2) + a(1, 3)*s.s_prop(3); a(2, 1)*s.s_prop(1) + a(2, 2)*s.s_prop(2) + a(2, 3)*s.s_prop(3); a(3, 1)*s.s_prop(1) + a(3, 2)*s.s_prop(2) + a(3, 3)*s.s_prop(3)];
            h__100 = sqrt(h__99(1)*h__99(1) + h__99(2)*h__99(2) + h__99(3)*h__99(3));
            if 1e-30 > h__100, h__100 = 1e-30; end
            s.s_prop = (h__99 / h__100);
        end
    end
    if ((s.mode == 8) && (mp.auto_next ~= 255))
        ok = ((sun_ok && (asils.pc.acos_(asils.pc.clamp((sun(1)*mp.sun_axis(1) + sun(2)*mp.sun_axis(2) + sun(3)*mp.sun_axis(3)), (-(1)), 1)) < (mp.sa_done_deg * (pi / 180)))) && s.ad_ok);
        if ok
            s.acq_hold = (s.acq_hold + dt);
        else
            s.acq_hold = 0;
        end
        if (s.acq_hold >= mp.sa_done_hold_s)
            s = asils.alg.modes.modes_enter(s, mp.auto_next);
        end
    end
end
